const file = n => path.join(DATA,n+'.json');
async function read(n){try{return JSON.parse(await fs.readFile(file(n),'utf8'))}catch(e){if(e.code==='ENOENT')return [];throw e}}
async function save(n,v){await fs.mkdir(DATA,{recursive:true});const tmp=file(n)+'.tmp';await fs.writeFile(tmp,JSON.stringify(v,null,2),'utf8');await fs.rename(tmp,file(n))}
function json(res,status,data){res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','x-frame-options':'DENY','referrer-policy':'strict-origin-when-cross-origin','permissions-policy':'camera=(), microphone=(), geolocation=()'});res.end(JSON.stringify(data))}
function readBody(req){return new Promise((resolve,reject)=>{let s='';req.on('data',c=>{s+=c;if(s.length>2000000){reject(new Error('large'));req.destroy()}});req.on('end',()=>{try{resolve(JSON.parse(s||'{}'))}catch{reject(new Error('json'))}});req.on('error',reject)})}
const clean = (v,n=500)=>String(v??'').trim().slice(0,n);
const digits = v => String(v||'').replace(/\D/g,'');
async function passwordResetRateLimited(phone,action,limit,windowMs){const now=Date.now(),key=action+':'+digits(phone);const rows=await read('passwordResetLimits');const row=rows.find(x=>x.key===key);const recent=(row?.times||[]).filter(t=>Number.isFinite(t)&&now-t<windowMs);if(recent.length>=limit){if(row)row.times=recent;await save('passwordResetLimits',rows);return true}const next={key,times:[...recent,now]};const out=rows.filter(x=>x.key!==key&&Array.isArray(x.times)&&x.times.some(t=>now-t<24*60*60*1000));out.push(next);await save('passwordResetLimits',out);return false}
function hashPassword(p,salt){return crypto.scryptSync(p,salt,64).toString('hex')}
function verifyPassword(p,salt,hash){try{return crypto.timingSafeEqual(Buffer.from(hashPassword(p,salt),'hex'),Buffer.from(hash,'hex'))}catch{return false}}
function newId(){return crypto.randomBytes(16).toString('hex')}
function newCode(){return 'UT-'+crypto.randomBytes(3).toString('hex').toUpperCase()}
async function currentUser(req){const h=String(req.headers.authorization||'');if(!h.startsWith('Bearer '))return null;const token=h.slice(7);if(!token)return null;const sessions=await read('sessions');const s=sessions.find(x=>x.token===token&&x.expires>Date.now());if(!s)return null;const users=await read('users');return users.find(x=>x.id===s.userId&&x.active!==false)||null}
async function needUser(req,res,role){const u=await currentUser(req);if(!u){json(res,401,{error:'Daxil olun və yenidən cəhd edin.'});return null}if(role&&u.role!==role){json(res,403,{error:'Bu bölməyə giriş icazəniz yoxdur.'});return null}if(u.role==='provider'&&u.status!=='approved'){json(res,403,{error:'Usta müraciətiniz hələ təsdiqlənməyib.'});return null}return u}
function adminOK(req){const expected=process.env.USTAP_ADMIN_TOKEN;if(!expected)return false;const h=String(req.headers.authorization||'');const got=h.startsWith('Bearer ')?h.slice(7):'';return !!got&&got.length===expected.length&&crypto.timingSafeEqual(Buffer.from(got),Buffer.from(expected))}
