function html(res,content,status=200){res.writeHead(status,{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','x-frame-options':'DENY','referrer-policy':'strict-origin-when-cross-origin','permissions-policy':'camera=(), microphone=(), geolocation=()','content-security-policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'"});res.end(content)}
function publicUser(u){return {id:u.id,role:u.role,name:u.name,phone:u.phone,email:u.email||'',city:u.city||'',categories:u.categories||[],status:u.status||'approved',commissionPlan:u.commissionPlan||'standard'}}
function commissionFor(price,rate,minimum){return Math.round(Math.max(Number(minimum)||0,Number(price)*Number(rate)/100)*100)/100}
async function getFinanceConfig(){let c=await read('finance');if(!c||Array.isArray(c)||typeof c!=='object')c={};const defaults={standardRate:10,minCommission:2,plans:[{id:'standard',name:'Standart',rate:10,description:'Əsas paket'},{id:'active',name:'Aktiv',rate:8,description:'Aktiv ustalar üçün'},{id:'pro',name:'Pro',rate:6,description:'Təcrübəli ustalar üçün'}],paymentsEnabled:false,provider:'not_connected'};return {...defaults,...c,plans:Array.isArray(c.plans)&&c.plans.length?c.plans:defaults.plans}}
function publicOrder(o){return {code:o.code,category:o.category,categoryName:o.categoryName,name:o.name,phone:o.phone,city:o.city,address:o.address,details:o.details,status:o.status,offers:o.offers||[],selectedOffer:o.selectedOffer||null,agreedPrice:o.agreedPrice??null,completionStatus:o.completionStatus||'not_started',completionSubmittedAt:o.completionSubmittedAt||null,completionConfirmedAt:o.completionConfirmedAt||null,paymentStatus:o.paymentStatus||'Gözləyir',commissionRate:o.commissionRate??null,commissionAmount:o.commissionAmount||0,commissionPlan:o.commissionPlan||null,paidAt:o.paidAt||null,paidMethod:o.paidMethod||null,createdAt:o.createdAt,createdAtISO:o.createdAtISO}}
async function createSession(res,user,message){const token=crypto.randomBytes(32).toString('hex'),sessions=await read('sessions');sessions.push({token,userId:user.id,expires:Date.now()+1000*60*60*24*30});await save('sessions',sessions);return json(res,201,{ok:true,token,user:publicUser(user),message})}
const server=http.createServer((req,res)=>{handle(req,res).catch(e=>{console.error('request failed',e);if(!res.headersSent)json(res,500,{error:'Server xətası. Bir az sonra yenidən cəhd edin.'});else res.end()})});
server.listen(PORT,'0.0.0.0',()=>console.log('UstaTap v2 listening on '+PORT));

